def top_words(text, min_length=1):
    """The five most common words, most common first, ties alphabetical."""
    counts = {}
    for word in words(text):
        if len(word) < min_length:
            continue
        if word in counts:
            counts[word] = counts[word] + 1
        else:
            counts[word] = 1
